#include <stdlib.h>
struct Node {
    char ch;
    struct Node *next;
};
struct Node *build(char *s) {
    struct Node *head=NULL;
    while(*s) {
        struct Node *node=malloc(sizeof(struct Node));
        node->ch=*s++;
        node->next=head;
        head=node;
    }
    return head;
}
int main(void) {
    struct Node *node=build("BEST");
    while(node) {
        putchar(node->ch);
        struct Node *old=node;
        node=node->next;
        free(old);
    }
    return 0;
}

