#include <stdio.h>
void place(int grid[3][3], const int values[9]) {
    for(int i=0;i<9;i++)
        grid[((i+1)/3)%3][(i+1)%3]=values[i];
}
int main(void) {
    int grid[3][3];
    int values[9]={5,2,7,4,1,8,3,6,9};
    int total=0;
    place(grid,values);
    for(int i=0;i<9;i++)
        total += grid[i/3][i%3] * (i%2==0 ? 1 : -1);
    printf("%d",total);
    return 0;
}

