    }
}
class Base {
    static int total=0;
    int value=1;
    Base() {
        total += ++value;
        update();
    }
    void update() {
        total += total;
    }
}
class Derived extends Base {
    int value=10;
    Derived() {
        value += 2;
        total += value++;
        update();
    }
    @Override
    void update() {
        total += total*2;
    }
}

int normalize(int values[], int count) {
    int index = 0;                 // ①
    while (index < count) {
        // ②
        if (values[index] < 0) {
            // ③
            values[index] = -values[index]; // ④
        }
        index++;                   // ⑤
    }
    return 1;                      // ⑥
}

public class Main {
    static int search(int[] data,int start,int end) {
        if(start>=end) return 0;
        int middle=(start+end)/2;
        return data[middle] + Math.max(
            search(data,start,middle),
            search(data,middle+1,end)
        );
    }
    public static void main(String[] args) {
        int[] data={3,5,8,12,17};
        System.out.println(search(data,0,data.length-1));
    }
}

class Node:
    def __init__(self,value):
        self.value=value
        self.children=[]

def build(values):
    nodes=[Node(value) for value in values]
    for index in range(1,len(nodes)):
        nodes[(index-1)//2].children.append(nodes[index])
    return nodes[0]

def odd_level_sum(node,level=0):
    own=node.value if level%2==1 else 0
    return own + sum(odd_level_sum(child,level+1) for child in node.children)

