#include <stdio.h>

void swap(int *ptr1, int *ptr2) {
    int temp = *ptr1;
    *ptr1 = *ptr2;
    *ptr2 = temp;
}

void func(int *arr, int n) {
    int *ptr1 = &arr[0];
    int *ptr2 = &arr[n - 1];
    while (ptr1 < ptr2) {
        swap(ptr1, ptr2);
        ptr1++;
        ptr2--;
    }
}

int main(void) {
    int arr[] = {1, 2, 3, 4, 5};
    func(arr, 5);
    printf("%d", arr[2]);
    return 0;
}

#include <stdio.h>

int factorial(int n, int from, int to, int temp) {
    if (n == 0) {
        return 0;
    } else {
        return factorial(n - 1, from, temp, to) + 1
             + factorial(n - 1, temp, to, from);
    }
}

int main(void) {
    int n = 3;
    printf("%d", factorial(n, 3, 2, 1));
    return 0;
}

#include <stdio.h>

void func(int **arr, int size) {
    for (int i = 0; i < size; i++) {
        *(*arr + i) = (*(*arr + i) + i) % size;
    }
}

