#include <stdio.h>
int main(void) {
    int a[5] = {9, 2, 10, 1, 7};
    for(int i=0;i<4;i++)
      for(int j=0;j<4-i;j++)
        if(a[j] > a[j+1]) {
          int t=a[j];
          a[j]=a[j+1];
          a[j+1]=t;
        }
    printf("%d %d", a[0], a[4]);
    return 0;
}

