class Printer {
    void print(Integer x) {
        System.out.print("I"+x);
    }
    void print(Number x) {
        System.out.print("N"+x);
    }
    void print(Object x) {
        System.out.print("O"+x);
    }
}
public class Main {
    public static void main(String[] args) {
        Object x=Integer.valueOf(7);
        new Printer().print(x);
    }
}

abstract class Base {
    abstract int f(int x);
    int g(int x) {
        return f(x)+1;
    }
}
class Sub extends Base {
    int f(int x) {
        return x*2;
    }
}
public class Main {
    public static void main(String[] args) {
        Base b=new Sub();
        System.out.print(b.g(5));
    }
}

class Parent {
    int value=14;
    int get() {
        return value;
    }
}
class Child extends Parent {
    int value=24;
    @Override
    int get() {
        return value+1;
    }
}
public class Main {
    public static void main(String[] args) {
        Parent x=new Child();
        System.out.print(x.value+" "+x.get());
    }
}

public class Main {
    static int f(int x) {
        return x+2;
    }
    static int f(double x) {
        return (int)x+5;
    }
    public static void main(String[] args) {
        System.out.print(f(8)+" "+f(8.5));
    }
}

